<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Storage;use App\Services\PremiumAccess;
class CommerceAdminController extends Controller {
 public function index(){return view('premiumCommerce',['rules'=>DB::table('premium_rules')->get(),'packs'=>DB::table('super_like_packs')->get(),'ads'=>DB::table('admin_ads')->orderByDesc('id')->get(),'content'=>DB::table('premium_content')->orderByDesc('id')->get(),'currencies'=>DB::table('currencies')->where('enabled',true)->get()]);}
 public function rules(Request $r){$v=$r->validate(['plan_code'=>'required|in:free,gold,pro','session_likes'=>'nullable|integer|min:1|max:10000','daily_rewinds'=>'nullable|integer|min:0|max:10000','weekly_stars'=>'required|integer|min:0|max:1000','hide_ads'=>'required|boolean','passport'=>'required|boolean']);if($v['plan_code']==='free' && ($v['session_likes']===null||(int)$v['daily_rewinds']!==0||$v['hide_ads']||$v['passport']))throw \Illuminate\Validation\ValidationException::withMessages(['plan_code'=>'Free requires a like limit, zero rewinds and no premium privacy.']);$code=$v['plan_code'];unset($v['plan_code']);DB::table('premium_rules')->where('plan_code',$code)->update($v);return back()->with('success','Allowances saved.');}
 public function pack(Request $r){$v=$r->validate(['id'=>'nullable|integer|exists:super_like_packs,id','name'=>'required|string|max:80','quantity'=>'required|integer|min:1|max:10000','reward_type'=>'required|in:star,coins','currency_code'=>'required|exists:currencies,code','amount_minor'=>'required|integer|min:1|max:1000000000','enabled'=>'required|boolean']);$id=$v['id']??null;unset($v['id']);$v['updated_at']=now();if($id)DB::table('super_like_packs')->where('id',$id)->update($v);else DB::table('super_like_packs')->insert($v+['created_at'=>now()]);return back()->with('success','Super Like pack saved.');}
 public function ad(Request $r){$v=$r->validate(['id'=>'nullable|integer|exists:admin_ads,id','title'=>'required|string|max:120','description'=>'required|string|max:2000','image_url'=>'required|url:https|max:500','target_url'=>'required|url:https|max:500','placement'=>'required|in:swipe,feed,both','starts_at'=>'required|date','ends_at'=>'required|date|after:starts_at','enabled'=>'required|boolean']);$id=$v['id']??null;unset($v['id']);$v['starts_at']=\Carbon\Carbon::parse($v['starts_at'])->utc();$v['ends_at']=\Carbon\Carbon::parse($v['ends_at'])->utc();$v['updated_at']=now();if($id)DB::table('admin_ads')->where('id',$id)->update($v);else DB::table('admin_ads')->insert($v+['created_at'=>now()]);return back()->with('success','Sponsored card saved.');}
 public function contentSave(Request $r){$v=$r->validate(['id'=>'nullable|integer|exists:premium_content,id','creator_id'=>'required|integer|exists:users,id','title'=>'required|string|max:120','description'=>'required|string|max:5000','currency_code'=>'required|exists:currencies,code','amount_minor'=>'required|integer|min:1|max:1000000000','published'=>'required|boolean','media'=>'nullable|file|mimetypes:image/jpeg,image/png,image/webp,video/mp4|max:25600']);$id=$v['id']??null;unset($v['id']);$file=$r->file('media');unset($v['media']);if(!$id&&!$file)throw \Illuminate\Validation\ValidationException::withMessages(['media'=>'Media required']);if($file){$v['media_path']=$file->store('premium-content','local');$v['mime']=$file->getMimeType();}$v['updated_at']=now();try{if($id)DB::table('premium_content')->where('id',$id)->update($v);else DB::table('premium_content')->insert($v+['created_at'=>now()]);}catch(\Throwable $e){if(isset($v['media_path']))Storage::disk('local')->delete($v['media_path']);throw $e;}return back()->with('success','Private paid content saved.');}
 public function ads(Request $r){$v=$r->validate(['placement'=>'required|in:swipe,feed']);if(PremiumAccess::hidesAds(auth('app_users')->user()?->id))return response()->json(['status'=>true,'data'=>[]]);return response()->json(['status'=>true,'data'=>DB::table('admin_ads')->where('enabled',true)->whereIn('placement',[$v['placement'],'both'])->where('starts_at','<=',now())->where('ends_at','>',now())->orderByDesc('id')->limit(20)->get(['id','title','description','image_url','target_url'])]);}
 public function content(){ $id=auth('app_users')->user()?->id;$me=auth('app_users')->user();$hidden=array_filter(explode(',',($me->blocked_users??'').','.($me->hidden_user_ids??'')));$rows=DB::table('premium_content')->where('published',true)->whereNotIn('creator_id',$hidden)->whereIn('creator_id',function($q)use($id){$q->select('id')->from('users')->where('is_block',0)->whereRaw("NOT FIND_IN_SET(?, COALESCE(blocked_users,''))",[$id]);})->orderByDesc('id')->limit(100)->get(['id','creator_id','title','description','currency_code','amount_minor','mime']);$unlocked=DB::table('content_unlocks')->where('user_id',$id)->pluck('content_id')->all();foreach($rows as $p)$p->unlocked=$p->creator_id===$id||in_array($p->id,$unlocked);return response()->json(['status'=>true,'data'=>$rows]);}
 public function media(int $id){$p=DB::table('premium_content')->where('id',$id)->where('published',true)->first();$me=auth('app_users')->user()?->id;if(DB::table('cash_wallets')->where('user_id',$me)->where('frozen',true)->exists())abort(403);if(!$p)abort(404);$creator=\App\Models\Users::find($p->creator_id);$viewer=auth('app_users')->user();if(!$creator||$creator->is_block||in_array((string)$me,explode(',',(string)$creator->blocked_users),true)||in_array((string)$creator->id,explode(',',(string)$viewer->blocked_users),true))abort(404);if($p->creator_id!==$me&&!DB::table('content_unlocks')->where('user_id',$me)->where('content_id',$id)->exists())abort(403);$path=Storage::disk('local')->path($p->media_path);if(!is_file($path))abort(404);$response=response()->file($path,['Content-Type'=>$p->mime,'X-Content-Type-Options'=>'nosniff']);$response->setPrivate();$response->headers->addCacheControlDirective('no-store');return $response;}
}
